#!/usr/bin/env python3
"""A compact behavioral reimplementation of the observed `stg` executable.

This program intentionally implements StGit-like behavior from observed CLI
interactions.  It relies on Git for object creation, diffs, and worktree
updates, while maintaining stack metadata in a small JSON file under .git and
mirroring the public refs used by StGit where practical.
"""
from __future__ import annotations

import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path
from typing import Dict, List, Optional, Tuple

try:
    from help_texts import HELP_TEXTS
except Exception:  # pragma: no cover
    HELP_TEXTS = {}

VERSION = "2.5.5"
FULL_VERSION = (
    "Stacked Git 2.5.5\n"
    "Copyright (C) 2005-2025 StGit authors\n"
    "This is free software: you are free to change and redistribute it.\n"
    "There is NO WARRANTY, to the extent permitted by law.\n"
    "SPDX-License-Identifier: GPL-2.0-only\n"
    "git version 2.34.1\n"
)

COMMANDS = [
    "branch", "clean", "commit", "completion", "delete", "diff", "edit",
    "email", "export", "files", "float", "fold", "goto", "hide", "id",
    "import", "init", "log", "name", "new", "next", "patches", "pick",
    "pop", "prev", "pull", "push", "rebase", "redo", "refresh", "rename",
    "repair", "reset", "series", "show", "sink", "spill", "squash", "sync",
    "top", "uncommit", "undo", "unhide", "version", "help",
]
ALIASES = ["add", "mv", "resolved", "rm", "status"]
ALL_COMMANDS = set(COMMANDS + ALIASES)
COLOR_VALUES = {"auto", "always", "ansi", "never"}


class StgError(Exception):
    def __init__(self, msg: str, code: int = 2):
        super().__init__(msg)
        self.msg = msg
        self.code = code


def stdout(text: str) -> None:
    sys.stdout.write(text)


def stderr(text: str) -> None:
    sys.stderr.write(text)


def println(text: str = "") -> None:
    sys.stdout.write(text + "\n")


def die(msg: str, code: int = 2) -> None:
    raise StgError(msg, code)


def usage_error(msg: str, usage: Optional[str] = None) -> None:
    if usage:
        raise StgError(f"{msg}\n\n{usage}\n\nFor more information, try '--help'.", 1)
    raise StgError(f"{msg}\n\nFor more information, try '--help'.", 1)


def run(cmd: List[str], *, cwd: Optional[str] = None, env: Optional[dict] = None,
        input: Optional[str] = None, capture: bool = True, check: bool = False,
        text: bool = True) -> subprocess.CompletedProcess:
    if capture:
        p = subprocess.run(cmd, cwd=cwd, env=env, input=input, text=text,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    else:
        p = subprocess.run(cmd, cwd=cwd, env=env, input=input, text=text)
    if check and p.returncode != 0:
        msg = (p.stderr or p.stdout or "").strip()
        raise RuntimeError(msg or f"command failed: {' '.join(cmd)}")
    return p


def git(args: List[str], **kw) -> subprocess.CompletedProcess:
    return run(["git"] + args, **kw)


def git_out(args: List[str], **kw) -> str:
    p = git(args, capture=True, **kw)
    if p.returncode != 0:
        raise RuntimeError((p.stderr or p.stdout).strip())
    return p.stdout.rstrip("\n")


def git_call(args: List[str]) -> int:
    return subprocess.call(["git"] + args)


def quote_branch(branch: str) -> str:
    # File-system friendly, reversible enough for local state names.
    return branch.replace("/", "%2F")


def in_git_repo() -> bool:
    return git(["rev-parse", "--git-dir"], capture=True).returncode == 0


class Repo:
    def __init__(self, require_branch: bool = True):
        p = git(["rev-parse", "--git-dir"], capture=True)
        if p.returncode != 0:
            die("Could not find a git repository in '.' or in any of its parents")
        gd = p.stdout.strip()
        self.gitdir = str(Path(gd).resolve()) if not os.path.isabs(gd) else gd
        wt = git(["rev-parse", "--show-toplevel"], capture=True)
        self.worktree = wt.stdout.strip() if wt.returncode == 0 else os.getcwd()
        bp = git(["symbolic-ref", "--quiet", "--short", "HEAD"], capture=True)
        if bp.returncode != 0:
            if require_branch:
                die("not on branch, HEAD is detached")
            self.branch = "HEAD"
        else:
            self.branch = bp.stdout.strip()
        self.state_dir = Path(self.gitdir) / "stg_state"
        self.state_dir.mkdir(parents=True, exist_ok=True)

    def head(self) -> str:
        p = git(["rev-parse", "--verify", "HEAD"], capture=True)
        if p.returncode != 0:
            refp = git(["symbolic-ref", "HEAD"], capture=True)
            ref = refp.stdout.strip() if refp.returncode == 0 else "HEAD"
            die(f"branch `{ref}` is unborn")
        return p.stdout.strip()

    def state_path(self, branch: Optional[str] = None) -> Path:
        return self.state_dir / (quote_branch(branch or self.branch) + ".json")

    def undo_path(self, branch: Optional[str] = None) -> Path:
        return self.state_dir / (quote_branch(branch or self.branch) + ".undo.json")

    def redo_path(self, branch: Optional[str] = None) -> Path:
        return self.state_dir / (quote_branch(branch or self.branch) + ".redo.json")

    def load(self, branch: Optional[str] = None, create_empty: bool = True) -> dict:
        path = self.state_path(branch)
        if path.exists():
            data = json.loads(path.read_text())
            # Backfill fields for older state files.
            data.setdefault("version", 5)
            data.setdefault("applied", [])
            data.setdefault("unapplied", [])
            data.setdefault("hidden", [])
            data.setdefault("patches", {})
            if "base" not in data:
                data["base"] = data.get("head") or self.head()
            return data
        # Import minimal state from refs/stacks if present.
        br = branch or self.branch
        sp = git(["show", f"refs/stacks/{br}:stack.json"], capture=True)
        if sp.returncode == 0:
            try:
                data = json.loads(sp.stdout)
                data.setdefault("base", self._infer_base(data))
                path.write_text(json.dumps(data, indent=2))
                return data
            except Exception:
                pass
        if not create_empty:
            die(f"StGit stack not initialized for branch `{br}`")
        base = self.head()
        return {"version": 5, "base": base, "applied": [], "unapplied": [],
                "hidden": [], "patches": {}, "initialized": False}

    def _infer_base(self, data: dict) -> str:
        if data.get("applied"):
            first = data["applied"][0]
            oid = data.get("patches", {}).get(first, {}).get("oid")
            if oid:
                pp = git(["rev-parse", f"{oid}^"], capture=True)
                if pp.returncode == 0:
                    return pp.stdout.strip()
        return data.get("head") or self.head()

    def save(self, state: dict, op: str, *, record_undo: bool = True) -> None:
        old = self.state_path()
        if record_undo and old.exists():
            self.undo_path().write_text(old.read_text())
            rp = self.redo_path()
            if rp.exists():
                rp.unlink()
        state = normalize_state(state)
        state["initialized"] = True
        old.write_text(json.dumps(state, indent=2, sort_keys=True))
        self.write_public_refs(state, op)

    def write_public_refs(self, state: dict, op: str) -> None:
        """Mirror enough of StGit's public refs for normal observation."""
        # Patch refs.
        existing = git(["for-each-ref", f"refs/patches/{self.branch}",
                        "--format=%(refname)"], capture=True)
        wanted = set(state.get("patches", {}).keys())
        if existing.returncode == 0:
            for ref in existing.stdout.splitlines():
                name = ref.split("/")[-1]
                if name not in wanted:
                    git(["update-ref", "-d", ref], capture=True)
        for name, meta in state.get("patches", {}).items():
            oid = meta.get("oid")
            if oid:
                git(["update-ref", f"refs/patches/{self.branch}/{name}", oid], capture=True)

        public = {
            "version": 5,
            "prev": self._current_stack_ref(),
            "head": self._safe_head(),
            "applied": state.get("applied", []),
            "unapplied": state.get("unapplied", []),
            "hidden": state.get("hidden", []),
            "patches": {n: {"oid": m.get("oid")} for n, m in state.get("patches", {}).items()},
        }
        with tempfile.TemporaryDirectory() as td:
            root = Path(td)
            (root / "stack.json").write_text(json.dumps(public, indent=2))
            patches_dir = root / "patches"
            patches_dir.mkdir()
            for name in wanted:
                (patches_dir / name).write_text(self.patch_blob_text(name, state))
            env = os.environ.copy()
            env["GIT_INDEX_FILE"] = str(root / "index")
            git(["read-tree", "--empty"], env=env, capture=True)
            git(["--work-tree", str(root), "add", "stack.json", "patches"], env=env, capture=True)
            tree = git_out(["write-tree"], env=env)
        parents: List[str] = []
        prev = public["prev"]
        if prev:
            parents += ["-p", prev]
        head = public["head"]
        if head:
            parents += ["-p", head]
        cp = git(["commit-tree", tree] + parents + ["-m", op], capture=True)
        if cp.returncode == 0:
            git(["update-ref", f"refs/stacks/{self.branch}", cp.stdout.strip()], capture=True)

    def _current_stack_ref(self) -> Optional[str]:
        p = git(["rev-parse", "--verify", f"refs/stacks/{self.branch}"], capture=True)
        return p.stdout.strip() if p.returncode == 0 else None

    def _safe_head(self) -> Optional[str]:
        p = git(["rev-parse", "--verify", "HEAD"], capture=True)
        return p.stdout.strip() if p.returncode == 0 else None

    def patch_blob_text(self, name: str, state: dict) -> str:
        meta = state.get("patches", {}).get(name, {})
        oid = meta.get("oid", "")
        if not oid:
            return ""
        tree = git(["rev-parse", f"{oid}^{{tree}}"], capture=True).stdout.strip()
        parent_tree = git(["rev-parse", f"{oid}^{{tree}}"], capture=True).stdout.strip()
        pp = git(["rev-parse", f"{oid}^{{tree}}"], capture=True)
        if pp.returncode == 0:
            tree = pp.stdout.strip()
        bp = git(["rev-parse", f"{oid}^^{{tree}}"], capture=True)
        if bp.returncode == 0:
            parent_tree = bp.stdout.strip()
        author = git(["show", "-s", "--format=%an <%ae>", oid], capture=True).stdout.strip()
        date = git(["show", "-s", "--format=%ai", oid], capture=True).stdout.strip()
        msg = git(["show", "-s", "--format=%B", oid], capture=True).stdout.rstrip("\n")
        return f"Bottom: {parent_tree}\nTop:    {tree}\nAuthor: {author}\nDate:   {date}\n\n{msg}\n"


def normalize_state(state: dict) -> dict:
    state.setdefault("version", 5)
    state.setdefault("applied", [])
    state.setdefault("unapplied", [])
    state.setdefault("hidden", [])
    state.setdefault("patches", {})
    state.setdefault("base", state.get("head"))
    for n, m in list(state["patches"].items()):
        if isinstance(m, str):
            state["patches"][n] = {"oid": m}
    return state


def current_branch() -> str:
    p = git(["symbolic-ref", "--quiet", "--short", "HEAD"], capture=True)
    if p.returncode != 0:
        die("not on branch, HEAD is detached")
    return p.stdout.strip()


def ensure_clean_index_worktree() -> None:
    if has_unmerged():
        die("resolve outstanding conflicts first")
    # StGit ignores untracked files for these cleanliness checks.
    if git(["diff", "--quiet"], capture=True).returncode != 0:
        die("worktree is dirty")
    if git(["diff", "--cached", "--quiet"], capture=True).returncode != 0:
        die("index is dirty")


def has_unmerged() -> bool:
    p = git(["diff", "--name-only", "--diff-filter=U"], capture=True)
    return p.returncode == 0 and bool(p.stdout.strip())


def is_staged_dirty() -> bool:
    return git(["diff", "--cached", "--quiet"], capture=True).returncode != 0


def is_unstaged_dirty() -> bool:
    return git(["diff", "--quiet"], capture=True).returncode != 0


def commit_tree(tree: str, parents: List[str], message: str, author_env: Optional[dict] = None) -> str:
    env = os.environ.copy()
    if author_env:
        env.update({k: v for k, v in author_env.items() if v})
    args = ["commit-tree", tree]
    for p in parents:
        if p:
            args += ["-p", p]
    args += ["-F", "-"]
    cp = git(args, input=message if message.endswith("\n") else message + "\n", env=env, capture=True)
    if cp.returncode != 0:
        stderr(cp.stderr)
        sys.exit(cp.returncode)
    return cp.stdout.strip()


def reset_to(commit: str, hard: bool = False) -> None:
    mode = "--hard" if hard else "--mixed"
    git(["reset", "-q", mode, commit], capture=True)


def tree_of(rev: str) -> str:
    return git_out(["rev-parse", f"{rev}^{{tree}}"])


def parent_of(rev: str) -> Optional[str]:
    p = git(["rev-parse", f"{rev}^"], capture=True)
    return p.stdout.strip() if p.returncode == 0 else None


def get_commit_message(oid: str) -> str:
    return git(["show", "-s", "--format=%B", oid], capture=True).stdout.rstrip("\n")


def get_subject(oid: str) -> str:
    return git(["show", "-s", "--format=%s", oid], capture=True).stdout.strip()


def get_author_name(oid: str) -> str:
    return git(["show", "-s", "--format=%an", oid], capture=True).stdout.strip()


def patch_parent(state: dict, name: str) -> str:
    app = state.get("applied", [])
    if name in app:
        i = app.index(name)
        if i == 0:
            return state["base"]
        return state["patches"][app[i - 1]]["oid"]
    oid = state["patches"][name]["oid"]
    pp = parent_of(oid)
    return pp or state["base"]


def all_patch_names(state: dict) -> List[str]:
    return state.get("applied", []) + state.get("unapplied", []) + state.get("hidden", [])


def find_patch(state: dict, name: str) -> bool:
    return name in state.get("patches", {})


def resolve_patch_or_rev(state: dict, rev: Optional[str]) -> str:
    if not rev:
        return git_out(["rev-parse", "HEAD"])
    if rev == "{base}":
        return state["base"]
    if rev in state.get("patches", {}):
        return state["patches"][rev]["oid"]
    p = git(["rev-parse", "--verify", f"{rev}^{{commit}}"], capture=True)
    if p.returncode == 0:
        return p.stdout.strip()
    die(f"patch `{rev}` does not exist")
    return ""


def name_for_rev(state: dict, rev: Optional[str]) -> str:
    oid = resolve_patch_or_rev(state, rev)
    full = git_out(["rev-parse", oid])
    if full == git_out(["rev-parse", state["base"]]):
        return "{base}"
    for n, m in state.get("patches", {}).items():
        if git_out(["rev-parse", m["oid"]]) == full:
            return n
    label = rev if rev else "HEAD"
    die(f"patch name not found for revision `{label}`")
    return ""


def validate_patch_name(name: str, argname: str = "[patchname]") -> None:
    shown = name
    if name.startswith("\\-"):
        name = name[1:]
    if "/" in name:
        usage_error(f"error: invalid value '{shown}' for '{argname}': invalid patch name `{shown}`: patch name may not contain '/'")
    if name.startswith("."):
        usage_error(f"error: invalid value '{shown}' for '{argname}': invalid patch name `{shown}`: patch name may not start with '.'")
    if ".." in name:
        usage_error(f"error: invalid value '{shown}' for '{argname}': invalid patch name `{shown}`: patch name may not contain '..'")
    if name.endswith("."):
        usage_error(f"error: invalid value '{shown}' for '{argname}': invalid patch name `{shown}`: patch name may not end with '.'")
    if not name or name in {"@", "{base}"}:
        usage_error(f"error: invalid value '{shown}' for '{argname}': invalid patch name `{shown}`")
    # Ask Git too for most other ref-format constraints.
    gp = git(["check-ref-format", "--allow-onelevel", name], capture=True)
    if gp.returncode != 0:
        usage_error(f"error: invalid value '{shown}' for '{argname}': invalid patch name `{shown}`")


def slugify_subject(subject: str) -> str:
    s = subject.strip().lower()
    out = []
    last_dash = False
    for ch in s:
        if ch.isalnum() or ch in "_.":
            out.append(ch)
            last_dash = False
        else:
            if not last_dash:
                out.append("-")
                last_dash = True
    slug = "".join(out).strip("-.")
    slug = re.sub(r"-+", "-", slug)
    return slug or "patch"


def unique_name(base: str, state: dict) -> str:
    if base not in state.get("patches", {}):
        return base
    i = 1
    while f"{base}-{i}" in state.get("patches", {}):
        i += 1
    return f"{base}-{i}"


def read_message_from_file(path: str) -> str:
    if path == "-":
        return sys.stdin.read().rstrip("\n")
    return Path(path).read_text().rstrip("\n")


def default_author_ident() -> str:
    name = git(["config", "user.name"], capture=True).stdout.strip() or ""
    email = git(["config", "user.email"], capture=True).stdout.strip() or ""
    return f"{name} <{email}>".strip()


class OptionParser:
    def __init__(self, args: List[str]):
        self.args = list(args)
        self.i = 0
        self.positionals: List[str] = []
        self.paths: List[str] = []
        self.opts: Dict[str, object] = {}

    def has_next(self) -> bool:
        return self.i < len(self.args)

    def peek(self) -> str:
        return self.args[self.i]

    def next(self) -> str:
        v = self.args[self.i]
        self.i += 1
        return v

    def value(self, opt: str, attached: Optional[str] = None) -> str:
        if attached is not None:
            if attached == "":
                usage_error(f"error: a value is required for '{opt} <message>' but none was supplied")
            return attached
        if not self.has_next() or self.peek().startswith("-"):
            # Message matches observed wording; good enough for other valued opts.
            usage_error(f"error: a value is required for '{opt} <message>' but none was supplied")
        return self.next()


def parse_message_options(args: List[str], *, command: str, allow_name: bool = False) -> Tuple[dict, List[str], List[str]]:
    p = OptionParser(args)
    opts: Dict[str, object] = {"message": None, "file": None, "author_env": {}, "trailers": []}
    while p.has_next():
        a = p.next()
        if a == "--":
            p.paths = p.args[p.i:]
            break
        if a in ("-m", "--message") or a.startswith("--message="):
            if opts.get("message") is not None:
                usage_error("error: the argument '--message <message>' cannot be used multiple times",
                            usage_for(command))
            val = p.value("--message", a.split("=", 1)[1] if "=" in a else None)
            opts["message"] = val
        elif a in ("-f", "--file") or a.startswith("--file="):
            val = p.value("--file", a.split("=", 1)[1] if "=" in a else None)
            opts["file"] = val
        elif allow_name and (a in ("-n", "--name") or a.startswith("--name=")):
            val = p.value("--name", a.split("=", 1)[1] if "=" in a else None)
            opts["name"] = val
        elif a in ("-r", "--refresh"):
            opts["refresh"] = True
        elif a in ("-i", "--index"):
            opts["index"] = True
        elif a in ("-F", "--force"):
            opts["force"] = True
        elif a in ("-e", "--edit", "-d", "--diff", "--no-verify", "--submodules", "--no-submodules", "--committer-date-is-author-date"):
            opts[a.lstrip("-").replace("-", "_")] = True
        elif a in ("--author", "--authname", "--authemail", "--authdate") or any(a.startswith(x + "=") for x in ("--author", "--authname", "--authemail", "--authdate")):
            opt = a.split("=", 1)[0]
            val = p.value(opt, a.split("=", 1)[1] if "=" in a else None)
            env = opts.setdefault("author_env", {})
            if opt == "--author":
                m = re.match(r"(.*)<([^>]+)>", val)
                if m:
                    env["GIT_AUTHOR_NAME"] = m.group(1).strip()
                    env["GIT_AUTHOR_EMAIL"] = m.group(2).strip()
            elif opt == "--authname":
                env["GIT_AUTHOR_NAME"] = val
            elif opt == "--authemail":
                env["GIT_AUTHOR_EMAIL"] = val
            elif opt == "--authdate":
                env["GIT_AUTHOR_DATE"] = val
        elif a.startswith("--signoff") or a.startswith("--ack") or a.startswith("--review") or a in ("-s",):
            if "=" in a:
                val = a.split("=", 1)[1]
            elif p.has_next() and not p.peek().startswith("-") and a not in ("-s",):
                val = p.next()
            else:
                val = default_author_ident()
            key = "Signed-off-by" if a.startswith("--signoff") or a == "-s" else ("Acked-by" if a.startswith("--ack") else "Reviewed-by")
            opts.setdefault("trailers", []).append(f"{key}: {val}")
        elif a.startswith("--color"):
            # command-local color; already handled globally when before command.
            if a == "--color" and p.has_next():
                p.next()
        elif a in ("-h", "--help"):
            opts["help"] = a
        elif a.startswith("-") and not (a.startswith("\\-")):
            usage_error(f"error: unexpected argument '{a}' found", usage_for(command))
        else:
            p.positionals.append(a[1:] if a.startswith("\\-") else a)
    msg = opts.get("message")
    if opts.get("file") is not None:
        msg = read_message_from_file(str(opts["file"]))
    if msg is not None and opts.get("trailers"):
        sep = "\n\n" if msg.strip() else ""
        msg = msg.rstrip("\n") + sep + "\n".join(opts["trailers"])
    opts["message"] = msg
    return opts, p.positionals, p.paths


def usage_for(command: str) -> str:
    text = HELP_TEXTS.get(command) or ""
    lines = []
    grab = False
    for line in text.splitlines():
        if line.startswith("Usage:"):
            grab = True
        if grab:
            if line == "" and lines:
                break
            lines.append(line)
    return "\n".join(lines) if lines else f"Usage: stg {command} [OPTIONS]"


def invoke_editor_for_message(initial: str = "") -> Optional[str]:
    editor = os.environ.get("GIT_EDITOR") or os.environ.get("VISUAL") or os.environ.get("EDITOR") or "vi"
    stderr("hint: Waiting for your editor to close the file...\n")
    with tempfile.NamedTemporaryFile("w+", delete=False) as f:
        f.write(initial)
        fname = f.name
    try:
        rc = subprocess.call(editor.split() + [fname])
        if rc != 0:
            stderr(f"error: running editor: {editor}: exited with status {rc}\n")
            return None
        data = Path(fname).read_text().strip("\n")
        return data
    except FileNotFoundError:
        stderr(f"error: running editor: {editor}: No such file or directory (os error 2)\n")
        return None
    finally:
        try:
            os.unlink(fname)
        except OSError:
            pass


def compute_refresh_tree(paths: List[str], *, use_index: bool = False, force: bool = False) -> str:
    if has_unmerged():
        die("resolve outstanding conflicts first")
    staged = is_staged_dirty()
    unstaged = is_unstaged_dirty()
    if use_index:
        return git_out(["write-tree"])
    if staged and unstaged and not force:
        die("the index is dirty; consider using `--index` or `--force`")
    if staged and not unstaged:
        return git_out(["write-tree"])
    # Worktree (and --force) mode: use a temporary index so untracked files are
    # not implicitly captured, while staged additions remain captured for force.
    with tempfile.NamedTemporaryFile(delete=False) as tf:
        idx = tf.name
    try:
        real_index = Path(git_out(["rev-parse", "--git-path", "index"]))
        if real_index.exists() and (staged or force):
            shutil.copyfile(real_index, idx)
        else:
            env = os.environ.copy(); env["GIT_INDEX_FILE"] = idx
            git(["read-tree", "HEAD"], env=env, capture=True)
        env = os.environ.copy(); env["GIT_INDEX_FILE"] = idx
        add_args = ["add", "-u"]
        if paths:
            add_args += ["--"] + paths
        git(add_args, env=env, capture=True)
        return git_out(["write-tree"], env=env)
    finally:
        try:
            os.unlink(idx)
        except OSError:
            pass


def state_initialized(repo: Repo, state: dict) -> bool:
    return bool(state.get("initialized")) or repo.state_path().exists() or git(["rev-parse", "--verify", f"refs/stacks/{repo.branch}"], capture=True).returncode == 0


