def prepare_message(opts: dict, patchname: Optional[str] = None) -> str:
    msg = opts.get("message")
    if msg is None:
        msg = invoke_editor_for_message("")
        if msg is None:
            sys.exit(2)
    # Git refuses fully empty messages in many paths; observed CLI also rejects
    # empty option values.  Keep whitespace messages as-is if supplied via file.
    return str(msg).strip("\n")


def cmd_new(args: List[str]) -> int:
    if help_requested(args, "new"):
        return 0
    opts, pos, paths = parse_message_options(args, command="new", allow_name=True)
    if opts.get("name") and pos:
        usage_error("error: the argument '--name <name>' cannot be used with '[patchname]'", usage_for("new"))
    if len(pos) > 1:
        usage_error(f"error: unexpected argument '{pos[1]}' found", usage_for("new"))
    if opts.get("index") and not (opts.get("refresh") or paths):
        usage_error("error: the following required arguments were not provided:\n  --refresh", usage_for("new"))
    repo = Repo(); repo.head()
    st = repo.load(create_empty=True)
    msg = prepare_message(opts)
    explicit = opts.get("name") or (pos[0] if pos else None)
    if explicit:
        patchname = str(explicit)
        validate_patch_name(patchname, "[patchname]" if not opts.get("name") else "--name <name>")
        if patchname in st.get("patches", {}):
            die(f"patch `{patchname}` already exists")
    else:
        patchname = unique_name(slugify_subject(msg.splitlines()[0] if msg.splitlines() else msg), st)
        validate_patch_name(patchname)
    refresh = bool(opts.get("refresh") or paths)
    if refresh:
        tree = compute_refresh_tree(paths, use_index=bool(opts.get("index")), force=bool(opts.get("force")))
    else:
        tree = tree_of("HEAD")
    parent = git_out(["rev-parse", "HEAD"])
    oid = commit_tree(tree, [parent], msg, opts.get("author_env"))
    reset_to(oid, hard=False)
    st.setdefault("patches", {})[patchname] = {"oid": oid}
    st.setdefault("applied", []).append(patchname)
    st.setdefault("unapplied", [])
    st.setdefault("hidden", [])
    st.setdefault("base", parent if len(st["applied"]) == 1 else st.get("base", parent))
    repo.save(st, f"new: {patchname}")
    println(f"> {patchname} (new)")
    return 0


def cmd_refresh(args: List[str]) -> int:
    if help_requested(args, "refresh"):
        return 0
    opts, pos, paths = parse_message_options(args, command="refresh", allow_name=False)
    patch = None
    # Parse -p/--patch manually from original args (parse_message_options ignores it as unexpected now), so redo simply.
    cleaned: List[str] = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-p", "--patch"):
            i += 1
            if i < len(args): patch = args[i]
        elif a.startswith("--patch="):
            patch = a.split("=", 1)[1]
        else:
            cleaned.append(a)
        i += 1
    # Reparse without -p if it was present and caused no paths issue.
    opts, pos, paths = parse_message_options(cleaned, command="refresh", allow_name=False)
    if pos:
        paths = pos + paths
    repo = Repo(); st = repo.load(create_empty=True)
    if not st.get("applied"):
        die("no patches applied")
    name = patch or st["applied"][-1]
    if name not in st.get("applied", []):
        die(f"patch `{name}` is not applied")
    if name != st["applied"][-1]:
        # Simplified support: non-top refresh is implemented by recreating the
        # commit and descendants only when no worktree tree changes are needed.
        pass
    old_oid = st["patches"][name]["oid"]
    new_msg = opts.get("message") if opts.get("message") is not None else get_commit_message(old_oid)
    tree = compute_refresh_tree(paths, use_index=bool(opts.get("index")), force=bool(opts.get("force")))
    parent = patch_parent(st, name)
    changed = tree != tree_of(old_oid) or new_msg != get_commit_message(old_oid)
    new_oid = commit_tree(tree, [parent], new_msg, opts.get("author_env"))
    # If refreshing top, reset to new commit.  If refreshing a lower patch, rebuild
    # descendants with the same trees/messages on top of the new parent.
    idx = st["applied"].index(name)
    st["patches"][name]["oid"] = new_oid
    cur_parent = new_oid
    for child in st["applied"][idx + 1:]:
        coid = st["patches"][child]["oid"]
        rebuilt = commit_tree(tree_of(coid), [cur_parent], get_commit_message(coid), None)
        st["patches"][child]["oid"] = rebuilt
        cur_parent = rebuilt
    reset_to(st["patches"][st["applied"][-1]]["oid"], hard=False)
    repo.save(st, "refresh")
    println("> refresh-temp (new)")
    println("- refresh-temp")
    println("# refresh-temp")
    if changed:
        println(f"& {name}")
    println(f"> {st['applied'][-1]}")
    return 0


def cmd_edit(args: List[str]) -> int:
    if help_requested(args, "edit"):
        return 0
    opts, pos, paths = parse_message_options(args, command="edit", allow_name=False)
    repo = Repo(); st = repo.load(create_empty=True)
    if not st.get("applied") and not pos:
        die("no patches applied")
    name = pos[0] if pos else st["applied"][-1]
    if name not in st.get("patches", {}):
        die(f"patch `{name}` does not exist")
    old = st["patches"][name]["oid"]
    msg = prepare_message(opts) if opts.get("message") is not None or opts.get("file") is not None else invoke_editor_for_message(get_commit_message(old))
    if msg is None:
        return 2
    new = commit_tree(tree_of(old), [patch_parent(st, name)], str(msg), opts.get("author_env"))
    st["patches"][name]["oid"] = new
    if name in st.get("applied", []):
        idx = st["applied"].index(name)
        cur = new
        for child in st["applied"][idx + 1:]:
            coid = st["patches"][child]["oid"]
            rebuilt = commit_tree(tree_of(coid), [cur], get_commit_message(coid), None)
            st["patches"][child]["oid"] = rebuilt
            cur = rebuilt
        reset_to(st["patches"][st["applied"][-1]]["oid"], hard=False)
    repo.save(st, "edit")
    println(f"& {name}")
    if st.get("applied"):
        println(f"> {st['applied'][-1]}")
    return 0


def cmd_pop(args: List[str]) -> int:
    if help_requested(args, "pop"):
        return 0
    repo = Repo(); st = repo.load(create_empty=True)
    if has_unmerged():
        die("resolve outstanding conflicts first")
    applied = st.get("applied", [])
    if not applied:
        die("no patches applied")
    all_flag = False; num = None; target = None
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-a", "--all"):
            all_flag = True
        elif a in ("-n", "--number"):
            i += 1; num = int(args[i])
        elif a.startswith("--number="):
            num = int(a.split("=", 1)[1])
        elif a.startswith("-"):
            pass
        else:
            target = a
        i += 1
    if all_flag:
        poplist = list(applied)
    elif num is not None:
        poplist = applied[-num:]
    elif target:
        if target not in st.get("patches", {}):
            die(f"patch `{target}` does not exist")
        if target not in applied:
            die(f"patch `{target}` is not applied")
        poplist = applied[applied.index(target):]
    else:
        poplist = [applied[-1]]
    # For non-top targets, simple StGit behavior is to pop the selected suffix.
    new_applied = applied[:len(applied) - len(poplist)]
    st["applied"] = new_applied
    st["unapplied"] = poplist + st.get("unapplied", [])
    new_head = st["patches"][new_applied[-1]]["oid"] if new_applied else st["base"]
    reset_to(new_head, hard=True)
    repo.save(st, "pop")
    println(format_range_line("-", poplist))
    if new_applied:
        println(f"> {new_applied[-1]}")
    return 0


def cmd_push(args: List[str]) -> int:
    if help_requested(args, "push"):
        return 0
    repo = Repo(); st = repo.load(create_empty=True)
    if has_unmerged():
        die("resolve outstanding conflicts first")
    unapplied = st.get("unapplied", [])
    if not unapplied:
        die("no unapplied patches")
    all_flag = False; num = None; target = None
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-a", "--all"):
            all_flag = True
        elif a in ("-n", "--number"):
            i += 1; num = int(args[i])
        elif a.startswith("--number="):
            num = int(a.split("=", 1)[1])
        elif a in ("--conflicts", "--merged") or a.startswith("--conflicts="):
            pass
        elif a.startswith("-"):
            pass
        else:
            target = a
        i += 1
    if all_flag:
        pushlist = list(unapplied)
    elif num is not None:
        pushlist = unapplied[:num]
    elif target:
        if target in st.get("applied", []):
            die(f"patch `{target}` is already applied")
        if target not in st.get("patches", {}):
            die(f"patch `{target}` does not exist")
        if target not in unapplied:
            die(f"patch `{target}` is not unapplied")
        pushlist = unapplied[:unapplied.index(target) + 1]
    else:
        pushlist = [unapplied[0]]
    for name in pushlist:
        old = st["patches"][name]["oid"]
        cur = git_out(["rev-parse", "HEAD"])
        if parent_of(old) == cur:
            new = old
            reset_to(new, hard=True)
        else:
            # Reapply the patch diff on current HEAD using cherry-pick where possible.
            cp = git(["cherry-pick", "-q", old], capture=True)
            if cp.returncode != 0:
                # Surface a StGit-like conflict message while leaving Git conflict state.
                println(f"+ {name} (conflict)")
                stderr("error: merge conflicts; resolve conflicts manually then refresh or undo the operation with `stg undo --hard`.\n")
                st["unapplied"].remove(name)
                st["applied"].append(name)
                repo.save(st, "push")
                return 3
            new = git_out(["rev-parse", "HEAD"])
            st["patches"][name]["oid"] = new
        st["unapplied"].remove(name)
        st["applied"].append(name)
    repo.save(st, "push")
    for n in pushlist[:-1]:
        println(f"+ {n}")
    println(f"> {pushlist[-1]}")
    return 0


def format_range_line(prefix: str, names: List[str]) -> str:
    if not names:
        return prefix
    if len(names) == 1:
        return f"{prefix} {names[0]}"
    return f"{prefix} {names[0]}..{names[-1]}"


def cmd_goto(args: List[str]) -> int:
    if help_requested(args, "goto"):
        return 0
    if not args:
        usage_error("error: the following required arguments were not provided:\n  <patch>", usage_for("goto"))
    target = next((a for a in args if not a.startswith("-")), None)
    repo = Repo(); st = repo.load(create_empty=True)
    if target not in st.get("patches", {}):
        die(f"patch `{target}` does not exist")
    if target in st.get("applied", []):
        idx = st["applied"].index(target)
        if idx == len(st["applied"]) - 1:
            println(f"> {target}")
            return 0
        return cmd_pop([target])
    if target in st.get("unapplied", []):
        return cmd_push([target])
    die(f"patch `{target}` is hidden")
    return 2


