def cmd_files(args: List[str]) -> int:
    if help_requested(args, "files"):
        return 0
    stat = False; bare = False; rev = None
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-s", "--stat"):
            stat = True
        elif a in ("-b", "--bare"):
            bare = True
        elif a.startswith("--color"):
            if a == "--color" and i + 1 < len(args): i += 1
        elif a.startswith("-"):
            pass
        else:
            rev = a
        i += 1
    repo = Repo(); st = repo.load(create_empty=True)
    if rev is None:
        if not st.get("applied"):
            die("no patches applied")
        rev = st["applied"][-1]
    oid = resolve_patch_or_rev(st, rev)
    par = parent_of(oid)
    if not par:
        return 0
    if stat:
        return git_call(["diff", "--stat", "--summary", par, oid])
    if bare:
        p = git(["diff", "--name-only", par, oid], capture=True)
        stdout(p.stdout); return p.returncode
    p = git(["diff", "--name-status", par, oid], capture=True)
    for line in p.stdout.splitlines():
        parts = line.split("\t")
        if parts:
            println(" ".join(parts))
    return p.returncode


def expand_patch_args(state: dict, specs: List[str]) -> List[str]:
    if not specs:
        return [state["applied"][-1]] if state.get("applied") else []
    order = all_patch_names(state)
    out: List[str] = []
    for s in specs:
        if ".." in s:
            a, b = s.split("..", 1)
            if a in order and b in order:
                ia, ib = order.index(a), order.index(b)
                if ia <= ib:
                    out.extend(order[ia:ib+1])
                else:
                    out.extend(order[ib:ia+1])
            else:
                out.append(s)
        else:
            out.append(s)
    return out


def cmd_show(args: List[str]) -> int:
    if help_requested(args, "show"):
        return 0
    stat = False; specs: List[str] = []; paths: List[str] = []
    after_dash = False
    i = 0
    while i < len(args):
        a = args[i]
        if after_dash:
            paths.append(a)
        elif a == "--":
            after_dash = True
        elif a == "--stat":
            stat = True
        elif a.startswith("--color"):
            if a == "--color" and i + 1 < len(args): i += 1
        elif a.startswith("-"):
            pass
        else:
            specs.append(a)
        i += 1
    repo = Repo(); st = repo.load(create_empty=True)
    names = expand_patch_args(st, specs)
    if not names:
        die("no patches applied")
    rc = 0
    first = True
    for spec in names:
        oid = resolve_patch_or_rev(st, spec)
        cmd = ["show", "--stat" if stat else "--patch", oid]
        if paths:
            cmd += ["--"] + paths
        p = git(cmd, capture=True)
        if not first and p.stdout and not p.stdout.startswith("\n"):
            stdout("\n")
        stdout(p.stdout)
        if p.stderr: stderr(p.stderr)
        rc = rc or p.returncode
        first = False
    return rc


def cmd_diff(args: List[str]) -> int:
    if help_requested(args, "diff"):
        return 0
    stat = False; rev = None; paths: List[str] = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("--stat", "--numstat", "--shortstat"):
            stat = True
        elif a in ("-r", "--range"):
            i += 1
            if i < len(args): rev = args[i]
        elif a.startswith("--range="):
            rev = a.split("=", 1)[1]
        elif a == "--":
            paths = args[i+1:]; break
        elif a.startswith("-"):
            pass
        else:
            paths.append(a)
        i += 1
    repo = Repo(); st = repo.load(create_empty=True)
    gargs = ["diff"]
    if stat: gargs.append("--stat")
    if rev:
        if ".." in rev:
            a, b = rev.split("..", 1)
            gargs += [resolve_patch_or_rev(st, a), resolve_patch_or_rev(st, b)]
        else:
            gargs += [resolve_patch_or_rev(st, rev), "HEAD"]
    if paths:
        gargs += ["--"] + paths
    return git_call(gargs)


def cmd_rename(args: List[str]) -> int:
    if help_requested(args, "rename"):
        return 0
    pos = [a for a in args if not a.startswith("-")]
    repo = Repo(); st = repo.load(create_empty=True)
    if len(pos) == 1:
        if not st.get("applied"):
            die("no patches applied")
        old, new = st["applied"][-1], pos[0]
    elif len(pos) >= 2:
        old, new = pos[0], pos[1]
    else:
        usage_error("error: the following required arguments were not provided:\n  <new-patch>", usage_for("rename"))
    if old not in st.get("patches", {}):
        die(f"patch `{old}` does not exist")
    validate_patch_name(new, "<new-patch>")
    if new in st.get("patches", {}):
        die(f"patch `{new}` already exists")
    st["patches"][new] = st["patches"].pop(old)
    for key in ("applied", "unapplied", "hidden"):
        st[key] = [new if x == old else x for x in st.get(key, [])]
    repo.save(st, "rename")
    println(f"{old} => {new}")
    if st.get("applied"):
        println(f"> {st['applied'][-1]}")
    return 0


def cmd_delete(args: List[str]) -> int:
    if help_requested(args, "delete"):
        return 0
    all_flag = "--all" in args or "-a" in args
    top_flag = "--top" in args
    specs = [a for a in args if not a.startswith("-")]
    repo = Repo(); st = repo.load(create_empty=True)
    if all_flag:
        specs = all_patch_names(st)
    elif top_flag:
        if not st.get("applied"): die("no patches applied")
        specs = [st["applied"][-1]]
    if not specs:
        usage_error("error: the following required arguments were not provided:\n  <patch>...", usage_for("delete"))
    # Expand ranges in patch specs.
    specs = expand_patch_args(st, specs)
    for s in specs:
        if s not in st.get("patches", {}):
            die(f"patch `{s}` does not exist")
    # Pop any applied patches from the first applied deletion upward.
    applied = st.get("applied", [])
    applied_to_delete = [s for s in specs if s in applied]
    popped: List[str] = []
    if applied_to_delete:
        idx = min(applied.index(s) for s in applied_to_delete)
        popped = applied[idx:]
        st["applied"] = applied[:idx]
        reset_to(st["patches"][st["applied"][-1]]["oid"] if st["applied"] else st["base"], hard=True)
    for s in specs:
        for key in ("applied", "unapplied", "hidden"):
            if s in st.get(key, []):
                st[key].remove(s)
        st.get("patches", {}).pop(s, None)
    repo.save(st, "delete")
    if popped:
        println(format_range_line("-", popped if len(popped) > 1 else [popped[0]]))
    println(format_range_line("#", specs))
    if st.get("applied"):
        println(f"> {st['applied'][-1]}")
    return 0


