def cmd_commit(args: List[str]) -> int:
    if help_requested(args, "commit"):
        return 0
    repo = Repo(); st = repo.load(create_empty=True)
    if not st.get("applied"):
        die("no patches applied")
    specs = [a for a in args if not a.startswith("-")]
    if not specs:
        specs = list(st["applied"])
    specs = expand_patch_args(st, specs)
    for n in specs:
        if n not in st.get("applied", []):
            die(f"patch `{n}` is not applied")
    # Commit bottom contiguous selected patches; other selections are removed in
    # place but base advances only across committed bottom patches.
    applied = st["applied"]
    bottom_count = 0
    for n in applied:
        if n in specs:
            bottom_count += 1
        else:
            break
    if bottom_count:
        st["base"] = st["patches"][applied[bottom_count - 1]]["oid"]
    st["applied"] = [n for n in applied if n not in specs]
    for n in specs:
        st["patches"].pop(n, None)
    repo.save(st, "commit")
    println(format_range_line("$", specs))
    if st.get("applied"):
        println(f"> {st['applied'][-1]}")
    return 0


def cmd_uncommit(args: List[str]) -> int:
    if help_requested(args, "uncommit"):
        return 0
    number = None; prefix = None; to_rev = None; exclusive = False; names: List[str] = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-n", "--number"):
            i += 1; number = int(args[i])
        elif a.startswith("--number="):
            number = int(a.split("=", 1)[1])
        elif a in ("-t", "--to"):
            i += 1; to_rev = args[i]
        elif a.startswith("--to="):
            to_rev = a.split("=", 1)[1]
        elif a in ("-x", "--exclusive"):
            exclusive = True
        elif a.startswith("-"):
            pass
        else:
            names.append(a)
        i += 1
    repo = Repo(); repo.head(); st = repo.load(create_empty=True)
    if st.get("applied"):
        die("cannot uncommit when patches are applied")
    if to_rev:
        rng = f"{to_rev}..HEAD" if exclusive else f"{to_rev}^..HEAD"
        revs = git(["rev-list", "--reverse", rng], capture=True).stdout.splitlines()
    else:
        if number is None:
            number = len(names) if names else 1
        revs = git(["rev-list", f"--max-count={number}", "HEAD"], capture=True).stdout.splitlines()
        revs.reverse()
    if not revs:
        die("no commits to uncommit")
    if names and number is not None and len(names) == 1 and number > 1:
        prefix = names[0]; names = [f"{prefix}{i}" for i in range(1, number + 1)]
    elif names:
        # Explicit names are supplied top-down; stack order is bottom-up.
        if len(names) != len(revs):
            die("number of patch names does not match number of commits")
        names = list(reversed(names))
    else:
        names = [unique_name(slugify_subject(get_subject(r)), st) for r in revs]
    if len(names) != len(revs):
        die("number of patch names does not match number of commits")
    base = parent_of(revs[0]) or revs[0]
    st["base"] = base
    st["applied"] = []
    for n, oid in zip(names, revs):
        validate_patch_name(n, "[patchname]")
        st["patches"][n] = {"oid": oid}
        st["applied"].append(n)
    repo.save(st, "uncommit")
    println(format_range_line("+", names))
    println(f"> {names[-1]}")
    return 0


def cmd_log(args: List[str]) -> int:
    if help_requested(args, "log"):
        return 0
    clear = "--clear" in args
    repo = Repo(); st = repo.load(create_empty=False)
    if clear:
        # Keep state but rewrite stack ref with a single current entry.
        repo.save(st, "log", record_undo=False)
        return 0
    specs = [a for a in args if not a.startswith("-")]
    ref = f"refs/stacks/{repo.branch}"
    p = git(["log", "--format=%h   %aD   %s", ref], capture=True)
    if p.returncode != 0:
        return 0
    lines = p.stdout.splitlines()
    # Remove leading zero from day to mimic observed `8 May` where Git may use `08 May`.
    for line in lines:
        line = re.sub(r", 0([1-9]) ", r", \1 ", line)
        if specs:
            if any(s in line for s in specs):
                println(line)
        else:
            println(line)
    return 0


