def cmd_branch(args: List[str]) -> int:
    if help_requested(args, "branch"):
        return 0
    repo = Repo(require_branch=False)
    if not args:
        println(current_branch()); return 0
    if args[0] in ("--list", "-l"):
        p = git(["for-each-ref", "refs/heads", "--format=%(refname:short)"], capture=True)
        branches = p.stdout.splitlines()
        cur = current_branch()
        width = max([len(b) for b in branches] + [0])
        for b in branches:
            mark = ">" if b == cur else " "
            s = "s" if (repo.state_path(b).exists() or git(["rev-parse", "--verify", f"refs/stacks/{b}"], capture=True).returncode == 0) else " "
            println(f"{mark} {s} \t{b.ljust(width)}  |")
        return 0
    if args[0] in ("--create", "-c"):
        if len(args) < 2:
            usage_error("error: the following required arguments were not provided:\n  <new-branch>", usage_for("branch"))
        newb = args[1]
        start = args[2] if len(args) > 2 else "HEAD"
        rc = git(["checkout", "-q", "-b", newb, start], capture=True).returncode
        if rc != 0: return rc
        stderr("info: Recording as a local branch\n")
        repo = Repo(); st = {"version": 5, "base": repo.head(), "applied": [], "unapplied": [], "hidden": [], "patches": {}, "initialized": True}
        repo.save(st, "initialize", record_undo=False)
        return 0
    if args[0] in ("--clone", "-C"):
        newb = args[1] if len(args) > 1 else current_branch() + "-clone"
        rc = git(["checkout", "-q", "-b", newb], capture=True).returncode
        return rc
    if args[0] in ("--rename", "-r"):
        if len(args) == 2:
            old, new = current_branch(), args[1]
        else:
            old, new = args[1], args[2]
        p = git(["branch", "-m", old, new], capture=True)
        if p.returncode != 0:
            stderr(p.stderr); return p.returncode
        oldp, newp = repo.state_path(old), repo.state_path(new)
        if oldp.exists(): oldp.rename(newp)
        git(["update-ref", f"refs/stacks/{new}", f"refs/stacks/{old}"], capture=True)
        git(["update-ref", "-d", f"refs/stacks/{old}"], capture=True)
        return 0
    if args[0] in ("--delete", "-D"):
        force = "--force" in args or "-f" in args
        branches = [a for a in args[1:] if not a.startswith("-")]
        b = branches[0] if branches else current_branch()
        if b == current_branch():
            # Move to a remaining branch if possible.
            p = git(["for-each-ref", "refs/heads", "--format=%(refname:short)"], capture=True)
            for cand in p.stdout.splitlines():
                if cand != b:
                    git(["checkout", "-q", cand], capture=True); break
        p = git(["branch", "-D" if force else "-d", b], capture=True)
        if p.returncode != 0 and not force:
            p = git(["branch", "-D", b], capture=True)
        sp = repo.state_path(b)
        if sp.exists(): sp.unlink()
        git(["update-ref", "-d", f"refs/stacks/{b}"], capture=True)
        return 0 if p.returncode == 0 else p.returncode
    if args[0] == "--cleanup":
        b = next((a for a in args[1:] if not a.startswith("-")), current_branch())
        sp = repo.state_path(b)
        if sp.exists(): sp.unlink()
        git(["update-ref", "-d", f"refs/stacks/{b}"], capture=True)
        return 0
    # Switch branch.
    b = args[0]
    if b == current_branch():
        die(f"{b} is already the current branch")
    p = git(["checkout", "-q", b], capture=True)
    if p.returncode != 0:
        stderr(p.stderr); return p.returncode
    return 0


def cmd_export(args: List[str]) -> int:
    if help_requested(args, "export"):
        return 0
    repo = Repo(); st = repo.load(create_empty=True)
    dirname = None; specs: List[str] = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-d", "--dir"):
            i += 1; dirname = args[i]
        elif a.startswith("--dir="):
            dirname = a.split("=", 1)[1]
        elif a.startswith("-"):
            pass
        else:
            specs.append(a)
        i += 1
    names = expand_patch_args(st, specs) if specs else all_patch_names(st)
    dirname = dirname or f"patches-{repo.branch.replace('/', '-') }"
    d = Path(dirname); d.mkdir(parents=True, exist_ok=True)
    (d / "series").write_text(f"# This series applies on Git commit {st.get('base')}\n" + "\n".join(names) + ("\n" if names else ""))
    for n in names:
        oid = st["patches"][n]["oid"]
        msg = get_commit_message(oid)
        author = git(["show", "-s", "--format=%an <%ae>", oid], capture=True).stdout.strip()
        par = parent_of(oid)
        diff = git(["diff", "--stat", par or f"{oid}^", oid], capture=True).stdout
        patch = git(["diff", par or f"{oid}^", oid], capture=True).stdout
        (d / n).write_text(f"{msg}\n\nFrom: {author}\n\n\n---\n{diff}\n{patch}")
    return 0


def cmd_import(args: List[str]) -> int:
    if help_requested(args, "import"):
        return 0
    files = [a for a in args if not a.startswith("-")]
    if not files:
        usage_error("error: the following required arguments were not provided:\n  <diff-path>", usage_for("import"))
    rc = 0
    for f in files:
        data = sys.stdin.read() if f == "-" else Path(f).read_text()
        # Subject: first non-empty non-header line.
        subject = None
        for line in data.splitlines():
            if line and not line.startswith(("From ", "diff --git", "---", "+++", "@@")):
                subject = line.strip(); break
        subject = subject or Path(f).stem
        name = slugify_subject(Path(f).stem if f != "-" else subject)
        gp = git(["apply", "--index", "-"], input=data, capture=True)
        if gp.returncode != 0:
            gp = git(["apply", "-"], input=data, capture=True)
        if gp.returncode != 0:
            stderr(gp.stderr); rc = gp.returncode; continue
        cmd_new([name, "-m", subject, "--refresh", "--index"])
    return rc


def cmd_pick(args: List[str]) -> int:
    if help_requested(args, "pick"):
