def cmd_float(args: List[str]) -> int:
    if help_requested(args, "float"):
        return 0
    specs = [a for a in args if not a.startswith("-")]
    if not specs:
        usage_error("error: the following required arguments were not provided:\n  <patch>...", usage_for("float"))
    repo = Repo(); st = repo.load(create_empty=True)
    # Move named patches to the front of unapplied, then push them.
    for n in specs:
        if n not in st.get("patches", {}): die(f"patch `{n}` does not exist")
        for key in ("applied", "unapplied"):
            if n in st.get(key, []): st[key].remove(n)
    st["unapplied"] = specs + st.get("unapplied", [])
    repo.save(st, "float")
    return cmd_push(["--number", str(len(specs))])


def cmd_squash(args: List[str]) -> int:
    if help_requested(args, "squash"):
        return 0
    opts, pos, paths = parse_message_options(args, command="squash", allow_name=True)
    if len(pos) < 2:
        usage_error("error: the following required arguments were not provided:\n  <patch>...", usage_for("squash"))
    repo = Repo(); st = repo.load(create_empty=True)
    names = pos
    for n in names:
        if n not in st.get("patches", {}): die(f"patch `{n}` does not exist")
    order = all_patch_names(st)
    names = sorted(names, key=lambda n: order.index(n) if n in order else 999)
    parent = patch_parent(st, names[0])
    topoid = st["patches"][names[-1]]["oid"]
    msg = opts.get("message") or "\n\n".join(get_commit_message(st["patches"][n]["oid"]) for n in names)
    newname = str(opts.get("name") or unique_name(slugify_subject(str(msg).splitlines()[0]), st))
    newoid = commit_tree(tree_of(topoid), [parent], str(msg), opts.get("author_env"))
    # Remove old, insert new where first was.
    for key in ("applied", "unapplied", "hidden"):
        lst = st.get(key, [])
        if any(n in lst for n in names):
            idx = min([lst.index(n) for n in names if n in lst])
            lst = [x for x in lst if x not in names]
            if key == ("applied" if names[0] in st.get("applied", []) else key):
                lst.insert(idx, newname)
            st[key] = lst
    for n in names: st["patches"].pop(n, None)
    st["patches"][newname] = {"oid": newoid}
    if newname in st.get("applied", []): reset_to(newoid, hard=True)
    repo.save(st, "squash")
    println(format_range_line("-", names))
    println(format_range_line("#", names))
    println(f"> {newname}")
    return 0


