def cmd_sink(args: List[str]) -> int:
    if help_requested(args, "sink"):
        return 0
    # Approximate as no-op reorder command.
    repo = Repo(); repo.load(create_empty=True)
    return 0


# ---- Help, completion, aliases, dispatch ------------------------------------


def help_requested(args: List[str], command: str) -> bool:
    if "--help" in args:
        stdout(HELP_TEXTS.get(command, "")); return True
    if "-h" in args:
        stdout(HELP_TEXTS.get(command + "_SHORT", HELP_TEXTS.get(command, ""))); return True
    return False


def cmd_completion(args: List[str]) -> int:
    if help_requested(args, "completion"):
        return 0
    if not args:
        usage_error("error: 'stg completion' requires a subcommand but one was not provided\n  [subcommands: bash, fish, zsh, list, man, help]", usage_for("completion"))
    sub = args[0]
    if sub == "list":
        if len(args) < 2:
            usage_error("error: 'stg completion list' requires a subcommand but one was not provided\n  [subcommands: aliases, commands, commands-and-aliases, help]", "Usage: stg completion list [OPTIONS] <COMMAND>")
        what = args[1]
        if what == "commands":
            stdout("\n".join(COMMANDS) + "\n")
        elif what == "aliases":
            stdout("\n".join(ALIASES) + "\n")
        elif what == "commands-and-aliases":
            stdout("\n".join(COMMANDS + ALIASES) + "\n")
        else:
            usage_error(f"error: unrecognized subcommand '{what}'", "Usage: stg completion list [OPTIONS] <COMMAND>")
        return 0
    if sub == "man":
        return 0
    if sub == "bash":
        stdout("# -*- shell-script -*-\n#\n# SPDX-License-Identifier: GPL-2.0-only\n#\n# bash completion script for StGit (automatically generated)\ncomplete -W \"" + " ".join(COMMANDS + ALIASES) + "\" stg\n")
        return 0
    if sub == "zsh":
        stdout("#compdef stg\n_arguments '1: :(" + " ".join(COMMANDS + ALIASES) + ")'\n")
        return 0
    if sub == "fish":
        stdout("# SPDX-License-Identifier: GPL-2.0-only\n#\n# Fish shell completion for StGit (stg)\ncomplete -c stg -f -a '" + " ".join(COMMANDS + ALIASES) + "'\n")
        return 0
    if sub == "help":
        stdout(HELP_TEXTS.get("completion", "")); return 0
    usage_error(f"error: unrecognized subcommand '{sub}'", usage_for("completion"))
    return 1


def cmd_help(args: List[str]) -> int:
    if not args:
        stdout(HELP_TEXTS.get("TOP_LONG", "")); return 0
    if args[0] == "help":
        stdout(HELP_TEXTS.get("help", "Print this message or the help of the given subcommand(s)\n\nUsage: stg help [COMMAND]...\n")); return 0
    cur = args[0]
    if cur not in ALL_COMMANDS:
        stderr(f"error: unrecognized subcommand '{cur}'\n\nUsage: stg [OPTIONS] <command> [...]\n       stg [OPTIONS] <-h|--help>\n       stg --version\n\nFor more information, try '--help'.\n")
        return 1
    if len(args) > 1:
        extra = args[1]
        stderr(f"error: unrecognized subcommand '{extra}'\n\n{usage_for(cur)}\n\nFor more information, try '--help'.\n")
        return 1
    stdout(HELP_TEXTS.get(cur, ""))
    return 0


def alias_command(cmd: str, args: List[str]) -> int:
    if cmd == "status":
        return git_call(["status", "-s"] + args)
    if cmd in ("add", "resolved"):
        return git_call(["add"] + args)
    if cmd == "rm":
        return git_call(["rm"] + args)
    if cmd == "mv":
        return git_call(["mv"] + args)
    return 1


DISPATCH = {
    "version": cmd_version,
    "init": cmd_init,
    "series": cmd_series,
    "top": cmd_top,
    "prev": cmd_prev,
    "next": cmd_next,
    "new": cmd_new,
    "refresh": cmd_refresh,
    "edit": cmd_edit,
    "pop": cmd_pop,
    "push": cmd_push,
    "goto": cmd_goto,
    "id": cmd_id,
    "name": cmd_name,
    "files": cmd_files,
    "show": cmd_show,
    "diff": cmd_diff,
    "rename": cmd_rename,
    "delete": cmd_delete,
    "clean": cmd_clean,
    "hide": cmd_hide,
    "unhide": cmd_unhide,
    "commit": cmd_commit,
    "uncommit": cmd_uncommit,
    "log": cmd_log,
    "undo": cmd_undo,
    "redo": cmd_redo,
    "repair": cmd_repair,
    "branch": cmd_branch,
    "export": cmd_export,
    "import": cmd_import,
    "pick": cmd_pick,
    "float": cmd_float,
    "squash": cmd_squash,
    "pull": cmd_pull,
    "rebase": cmd_rebase,
    "reset": cmd_reset,
    "spill": cmd_spill,
    "fold": cmd_fold,
    "sync": cmd_sync,
    "email": cmd_email,
    "patches": cmd_patches,
    "sink": cmd_sink,
    "completion": cmd_completion,
    "help": cmd_help,
}


def parse_global(argv: List[str]) -> Tuple[List[str], Optional[int]]:
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "-C":
            if i + 1 >= len(argv):
                usage_error("error: a value is required for '-C <path>' but none was supplied")
            path = argv[i+1]
            os.chdir(path)
            del argv[i:i+2]
            continue
        if a.startswith("-C") and a != "-C" and len(a) > 2:
            os.chdir(a[2:])
            del argv[i]
            continue
        if a == "--color" or a.startswith("--color="):
            val = None
            if a == "--color":
                if i + 1 >= len(argv):
                    usage_error("error: a value is required for '--color <when>' but none was supplied")
                val = argv[i+1]
                del argv[i:i+2]
            else:
                val = a.split("=", 1)[1]
                del argv[i]
            if val not in COLOR_VALUES:
                stderr(f"error: invalid value '{val}' for '--color <when>'\n  [possible values: auto, always, ansi, never]\n\nFor more information, try '--help'.\n")
                return argv, 1
            continue
        break
    return argv, None


def main(argv: List[str]) -> int:
    argv, early = parse_global(list(argv))
    if early is not None:
        return early
    if not argv:
        stderr(HELP_TEXTS.get("TOP_NOARGS", HELP_TEXTS.get("TOP_SHORT", "")))
        return 1
    if argv[0] == "--version":
        stdout(FULL_VERSION); return 0
    if argv[0] == "version":
        return cmd_version(argv[1:])
    if argv[0] == "--help":
        stdout(HELP_TEXTS.get("TOP_LONG", "")); return 0
    if argv[0] == "-h":
        stdout(HELP_TEXTS.get("TOP_SHORT", HELP_TEXTS.get("TOP_LONG", ""))); return 0
    cmd, args = argv[0], argv[1:]
    if cmd not in ALL_COMMANDS:
        stderr(f"error: unrecognized subcommand '{cmd}'\n\nUsage: stg [OPTIONS] <command> [...]\n       stg [OPTIONS] <-h|--help>\n       stg --version\n\nFor more information, try '--help'.\n")
        return 1
    if cmd in ALIASES:
        return alias_command(cmd, args)
    func = DISPATCH.get(cmd)
    if func is None:
        if help_requested(args, cmd):
            return 0
        die(f"command `{cmd}` is not implemented")
    return func(args)


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except StgError as e:
        # Messages passed through usage_error already include the leading "error:".
        if e.msg.startswith("error:"):
            stderr(e.msg + ("" if e.msg.endswith("\n") else "\n"))
        else:
            stderr(f"error: {e.msg}\n")
        sys.exit(e.code)
    except BrokenPipeError:
        sys.exit(1)
