def cmd_version(args: List[str]) -> int:
    if "--help" in args:
        stdout(HELP_TEXTS.get("version", "")); return 0
    if "-h" in args:
        stdout(HELP_TEXTS.get("version_SHORT", HELP_TEXTS.get("version", ""))); return 0
    short = any(a in ("-s", "--short") for a in args)
    if short:
        println(f"stg {VERSION}")
    else:
        stdout(FULL_VERSION)
    return 0


def cmd_init(args: List[str]) -> int:
    if help_requested(args, "init"):
        return 0
    branch = None
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-b", "--branch"):
            i += 1; branch = args[i] if i < len(args) else None
        elif a.startswith("--branch="):
            branch = a.split("=", 1)[1]
        i += 1
    repo = Repo()
    if branch and branch != repo.branch:
        # Minimal support: initialize named branch without checking it out.
        hp = git(["rev-parse", "--verify", f"refs/heads/{branch}^{{commit}}"], capture=True)
        if hp.returncode != 0:
            die(f"branch `refs/heads/{branch}` is unborn")
        if repo.state_path(branch).exists() or git(["rev-parse", "--verify", f"refs/stacks/{branch}"], capture=True).returncode == 0:
            die(f"StGit stack already initialized for branch `{branch}`")
        old_branch = repo.branch
        repo.branch = branch
        st = {"version": 5, "base": hp.stdout.strip(), "applied": [], "unapplied": [], "hidden": [], "patches": {}, "initialized": True}
        repo.save(st, "initialize", record_undo=False)
        repo.branch = old_branch
        return 0
    repo.head()
    st = repo.load(create_empty=True)
    if state_initialized(repo, st):
        die(f"StGit stack already initialized for branch `{repo.branch}`")
    st["base"] = repo.head()
    st["initialized"] = True
    repo.save(st, "initialize", record_undo=False)
    return 0


def cmd_series(args: List[str]) -> int:
    if help_requested(args, "series"):
        return 0
    repo = Repo()
    state = repo.load(create_empty=True)
    select_applied = select_unapplied = select_hidden = False
    all_sel = False
    no_prefix = False
    desc = False
    author = False
    count = False
    reverse = False
    commit_id = False
    empty = False
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-A", "--applied"):
            select_applied = True
        elif a in ("-U", "--unapplied"):
            select_unapplied = True
        elif a in ("-H", "--hidden"):
            select_hidden = True
        elif a in ("-a", "--all"):
            all_sel = True
        elif a in ("-P", "--no-prefix", "--noprefix"):
            no_prefix = True
        elif a in ("-d", "--description"):
            desc = True
        elif a == "--no-description":
            desc = False
        elif a == "--author":
            author = True
        elif a in ("-c", "--count"):
            count = True
        elif a in ("-r", "--reverse"):
            reverse = True
        elif a.startswith("-i") or a.startswith("--commit-id"):
            commit_id = True
            if a in ("-i", "--commit-id") and i + 1 < len(args) and not args[i+1].startswith("-"):
                i += 1
        elif a in ("-e", "--empty"):
            empty = True
        elif a in ("-s", "--short") or a.startswith("--short"):
            if i + 1 < len(args) and not args[i+1].startswith("-"):
                i += 1
        elif a in ("-b", "--branch", "-m", "--missing"):
            if i + 1 < len(args): i += 1
        elif a.startswith("--color"):
            if a == "--color" and i + 1 < len(args): i += 1
        elif a.startswith("-"):
            pass
        i += 1
    selected: List[Tuple[str, str]] = []
    if all_sel:
        select_applied = select_unapplied = select_hidden = True
    if not (select_applied or select_unapplied or select_hidden):
        select_applied = select_unapplied = True
    if select_applied:
        for n in state.get("applied", []): selected.append(("applied", n))
    if select_unapplied:
        for n in state.get("unapplied", []): selected.append(("unapplied", n))
    if select_hidden:
        for n in state.get("hidden", []): selected.append(("hidden", n))
    if reverse:
        selected.reverse()
    if count:
        println(str(len(selected)))
        return 0
    width = max([len(n) for _, n in selected] + [0])
    for kind, name in selected:
        prefix = ""
        if not no_prefix:
            if kind == "hidden":
                prefix = "!"
            elif kind == "unapplied":
                prefix = "-"
            else:
                prefix = ">" if state.get("applied", []) and name == state["applied"][-1] else "+"
        emptymark = ""
        if empty:
            emptymark = "*" if is_patch_empty(state, name) else " "
        main = name if no_prefix else f"{prefix} {name}"
        if empty:
            main = emptymark + main
        extras: List[str] = []
        oid = state.get("patches", {}).get(name, {}).get("oid")
        if commit_id and oid:
            extras.append(git_out(["rev-parse", "--short", oid]))
        if desc and oid:
            extras.append(get_subject(oid))
        if author and oid:
            extras.append(get_author_name(oid))
        if extras:
            if no_prefix:
                main = name.ljust(width)
            else:
                main = f"{prefix} {name.ljust(width)}"
                if empty:
                    main = emptymark + main
            main += " # " + " ".join(extras)
        println(main)
    return 0


def is_patch_empty(state: dict, name: str) -> bool:
    oid = state.get("patches", {}).get(name, {}).get("oid")
    if not oid:
        return True
    par = parent_of(oid)
    if not par:
        return False
    return tree_of(oid) == tree_of(par)


def cmd_top(args: List[str]) -> int:
    if help_requested(args, "top"):
        return 0
    repo = Repo(); st = repo.load(create_empty=True)
    if not st.get("applied"):
        die("no patches applied")
    println(st["applied"][-1]); return 0


def cmd_prev(args: List[str]) -> int:
    if help_requested(args, "prev"):
        return 0
    repo = Repo(); st = repo.load(create_empty=True)
    if len(st.get("applied", [])) < 2:
        die("not enough patches applied")
    println(st["applied"][-2]); return 0


def cmd_next(args: List[str]) -> int:
    if help_requested(args, "next"):
        return 0
    repo = Repo(); st = repo.load(create_empty=True)
    if not st.get("unapplied"):
