        elif a.startswith("--color"):
            if a == "--color" and i + 1 < len(args): i += 1
        elif a.startswith("-"):
            pass
        else:
            rev = a
        i += 1
    repo = Repo(); st = repo.load(create_empty=True)
    if rev is None:
        if not st.get("applied"):
            die("no patches applied")
        rev = st["applied"][-1]
    oid = resolve_patch_or_rev(st, rev)
    par = parent_of(oid)
    if not par:
        return 0
    if stat:
        return git_call(["diff", "--stat", "--summary", par, oid])
    if bare:
        p = git(["diff", "--name-only", par, oid], capture=True)
        stdout(p.stdout); return p.returncode
    p = git(["diff", "--name-status", par, oid], capture=True)
    for line in p.stdout.splitlines():
        parts = line.split("\t")
        if parts:
