    return p.returncode


def expand_patch_args(state: dict, specs: List[str]) -> List[str]:
    if not specs:
        return [state["applied"][-1]] if state.get("applied") else []
    order = all_patch_names(state)
    out: List[str] = []
    for s in specs:
        if ".." in s:
            a, b = s.split("..", 1)
            if a in order and b in order:
                ia, ib = order.index(a), order.index(b)
                if ia <= ib:
                    out.extend(order[ia:ib+1])
                else:
                    out.extend(order[ib:ia+1])
            else:
                out.append(s)
        else:
            out.append(s)
    return out


def cmd_show(args: List[str]) -> int:
