def cmd_rename(args: List[str]) -> int:
    if help_requested(args, "rename"):
        return 0
    pos = [a for a in args if not a.startswith("-")]
    repo = Repo(); st = repo.load(create_empty=True)
    if len(pos) == 1:
        if not st.get("applied"):
            die("no patches applied")
        old, new = st["applied"][-1], pos[0]
    elif len(pos) >= 2:
        old, new = pos[0], pos[1]
    else:
        usage_error("error: the following required arguments were not provided:\n  <new-patch>", usage_for("rename"))
    if old not in st.get("patches", {}):
        die(f"patch `{old}` does not exist")
    validate_patch_name(new, "<new-patch>")
    if new in st.get("patches", {}):
        die(f"patch `{new}` already exists")
    st["patches"][new] = st["patches"].pop(old)
    for key in ("applied", "unapplied", "hidden"):
        st[key] = [new if x == old else x for x in st.get(key, [])]
    repo.save(st, "rename")
    println(f"{old} => {new}")
    if st.get("applied"):
        println(f"> {st['applied'][-1]}")
    return 0


def cmd_delete(args: List[str]) -> int:
    if help_requested(args, "delete"):
        return 0
    all_flag = "--all" in args or "-a" in args
    top_flag = "--top" in args
    specs = [a for a in args if not a.startswith("-")]
    repo = Repo(); st = repo.load(create_empty=True)
    if all_flag:
        specs = all_patch_names(st)
    elif top_flag:
        if not st.get("applied"): die("no patches applied")
        specs = [st["applied"][-1]]
    if not specs:
        usage_error("error: the following required arguments were not provided:\n  <patch>...", usage_for("delete"))
    # Expand ranges in patch specs.
    specs = expand_patch_args(st, specs)
    for s in specs:
        if s not in st.get("patches", {}):
            die(f"patch `{s}` does not exist")
    # Pop any applied patches from the first applied deletion upward.
    applied = st.get("applied", [])
    applied_to_delete = [s for s in specs if s in applied]
    popped: List[str] = []
    if applied_to_delete:
        idx = min(applied.index(s) for s in applied_to_delete)
        popped = applied[idx:]
        st["applied"] = applied[:idx]
        reset_to(st["patches"][st["applied"][-1]]["oid"] if st["applied"] else st["base"], hard=True)
    for s in specs:
        for key in ("applied", "unapplied", "hidden"):
            if s in st.get(key, []):
                st[key].remove(s)
        st.get("patches", {}).pop(s, None)
    repo.save(st, "delete")
    if popped:
        println(format_range_line("-", popped if len(popped) > 1 else [popped[0]]))
    println(format_range_line("#", specs))
    if st.get("applied"):
        println(f"> {st['applied'][-1]}")
    return 0


