def cmd_branch(args: List[str]) -> int:
    if help_requested(args, "branch"):
        return 0
    repo = Repo(require_branch=False)
    if not args:
        println(current_branch()); return 0
    if args[0] in ("--list", "-l"):
        p = git(["for-each-ref", "refs/heads", "--format=%(refname:short)"], capture=True)
        branches = p.stdout.splitlines()
        cur = current_branch()
        width = max([len(b) for b in branches] + [0])
        for b in branches:
            mark = ">" if b == cur else " "
            s = "s" if (repo.state_path(b).exists() or git(["rev-parse", "--verify", f"refs/stacks/{b}"], capture=True).returncode == 0) else " "
            println(f"{mark} {s} \t{b.ljust(width)}  |")
        return 0
    if args[0] in ("--create", "-c"):
        if len(args) < 2:
            usage_error("error: the following required arguments were not provided:\n  <new-branch>", usage_for("branch"))
        newb = args[1]
        start = args[2] if len(args) > 2 else "HEAD"
        rc = git(["checkout", "-q", "-b", newb, start], capture=True).returncode
        if rc != 0: return rc
        stderr("info: Recording as a local branch\n")
        repo = Repo(); st = {"version": 5, "base": repo.head(), "applied": [], "unapplied": [], "hidden": [], "patches": {}, "initialized": True}
        repo.save(st, "initialize", record_undo=False)
        return 0
    if args[0] in ("--clone", "-C"):
        newb = args[1] if len(args) > 1 else current_branch() + "-clone"
        rc = git(["checkout", "-q", "-b", newb], capture=True).returncode
        return rc
    if args[0] in ("--rename", "-r"):
        if len(args) == 2:
            old, new = current_branch(), args[1]
        else:
            old, new = args[1], args[2]
        p = git(["branch", "-m", old, new], capture=True)
        if p.returncode != 0:
            stderr(p.stderr); return p.returncode
        oldp, newp = repo.state_path(old), repo.state_path(new)
        if oldp.exists(): oldp.rename(newp)
        git(["update-ref", f"refs/stacks/{new}", f"refs/stacks/{old}"], capture=True)
        git(["update-ref", "-d", f"refs/stacks/{old}"], capture=True)
        return 0
    if args[0] in ("--delete", "-D"):
        force = "--force" in args or "-f" in args
        branches = [a for a in args[1:] if not a.startswith("-")]
        b = branches[0] if branches else current_branch()
        if b == current_branch():
            # Move to a remaining branch if possible.
            p = git(["for-each-ref", "refs/heads", "--format=%(refname:short)"], capture=True)
            for cand in p.stdout.splitlines():
                if cand != b:
                    git(["checkout", "-q", cand], capture=True); break
        p = git(["branch", "-D" if force else "-d", b], capture=True)
        if p.returncode != 0 and not force:
            p = git(["branch", "-D", b], capture=True)
        sp = repo.state_path(b)
        if sp.exists(): sp.unlink()
        git(["update-ref", "-d", f"refs/stacks/{b}"], capture=True)
        return 0 if p.returncode == 0 else p.returncode
    if args[0] == "--cleanup":
        b = next((a for a in args[1:] if not a.startswith("-")), current_branch())
        sp = repo.state_path(b)
        if sp.exists(): sp.unlink()
        git(["update-ref", "-d", f"refs/stacks/{b}"], capture=True)
        return 0
    # Switch branch.
    b = args[0]
    if b == current_branch():
        die(f"{b} is already the current branch")
    p = git(["checkout", "-q", b], capture=True)
    if p.returncode != 0:
        stderr(p.stderr); return p.returncode
    return 0


def cmd_export(args: List[str]) -> int:
    if help_requested(args, "export"):
        return 0
    repo = Repo(); st = repo.load(create_empty=True)
    dirname = None; specs: List[str] = []
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-d", "--dir"):
            i += 1; dirname = args[i]
        elif a.startswith("--dir="):
            dirname = a.split("=", 1)[1]
        elif a.startswith("-"):
            pass
        else:
            specs.append(a)
        i += 1
    names = expand_patch_args(st, specs) if specs else all_patch_names(st)
    dirname = dirname or f"patches-{repo.branch.replace('/', '-') }"
    d = Path(dirname); d.mkdir(parents=True, exist_ok=True)
    (d / "series").write_text(f"# This series applies on Git commit {st.get('base')}\n" + "\n".join(names) + ("\n" if names else ""))
    for n in names:
        oid = st["patches"][n]["oid"]
        msg = get_commit_message(oid)
        author = git(["show", "-s", "--format=%an <%ae>", oid], capture=True).stdout.strip()
        par = parent_of(oid)
        diff = git(["diff", "--stat", par or f"{oid}^", oid], capture=True).stdout
        patch = git(["diff", par or f"{oid}^", oid], capture=True).stdout
        (d / n).write_text(f"{msg}\n\nFrom: {author}\n\n\n---\n{diff}\n{patch}")
    return 0


def cmd_import(args: List[str]) -> int:
    if help_requested(args, "import"):
        return 0
    files = [a for a in args if not a.startswith("-")]
    if not files:
        usage_error("error: the following required arguments were not provided:\n  <diff-path>", usage_for("import"))
    rc = 0
    for f in files:
        data = sys.stdin.read() if f == "-" else Path(f).read_text()
        # Subject: first non-empty non-header line.
        subject = None
        for line in data.splitlines():
            if line and not line.startswith(("From ", "diff --git", "---", "+++", "@@")):
                subject = line.strip(); break
        subject = subject or Path(f).stem
        name = slugify_subject(Path(f).stem if f != "-" else subject)
        gp = git(["apply", "--index", "-"], input=data, capture=True)
        if gp.returncode != 0:
            gp = git(["apply", "-"], input=data, capture=True)
        if gp.returncode != 0:
            stderr(gp.stderr); rc = gp.returncode; continue
        cmd_new([name, "-m", subject, "--refresh", "--index"])
    return rc


def cmd_pick(args: List[str]) -> int:
    if help_requested(args, "pick"):
        return 0
    sources = [a for a in args if not a.startswith("-")]
    if not sources:
        usage_error("error: the following required arguments were not provided:\n  <source>...", usage_for("pick"))
    repo = Repo(); st = repo.load(create_empty=True)
    for src in sources:
        oid = git_out(["rev-parse", f"{src}^{{commit}}"])
        name = unique_name(slugify_subject(get_subject(oid)), st)
        cp = git(["cherry-pick", "-q", oid], capture=True)
        if cp.returncode != 0:
            stderr(cp.stderr); return cp.returncode
        newoid = git_out(["rev-parse", "HEAD"])
        st["patches"][name] = {"oid": newoid}
        st["applied"].append(name)
        println(f"> {name}")
    repo.save(st, "pick")
    return 0


def cmd_float(args: List[str]) -> int:
    if help_requested(args, "float"):
        return 0
    specs = [a for a in args if not a.startswith("-")]
    if not specs:
        usage_error("error: the following required arguments were not provided:\n  <patch>...", usage_for("float"))
    repo = Repo(); st = repo.load(create_empty=True)
    # Move named patches to the front of unapplied, then push them.
    for n in specs:
        if n not in st.get("patches", {}): die(f"patch `{n}` does not exist")
        for key in ("applied", "unapplied"):
            if n in st.get(key, []): st[key].remove(n)
    st["unapplied"] = specs + st.get("unapplied", [])
    repo.save(st, "float")
    return cmd_push(["--number", str(len(specs))])


def cmd_squash(args: List[str]) -> int:
    if help_requested(args, "squash"):
        return 0
    opts, pos, paths = parse_message_options(args, command="squash", allow_name=True)
    if len(pos) < 2:
        usage_error("error: the following required arguments were not provided:\n  <patch>...", usage_for("squash"))
    repo = Repo(); st = repo.load(create_empty=True)
    names = pos
    for n in names:
        if n not in st.get("patches", {}): die(f"patch `{n}` does not exist")
    order = all_patch_names(st)
    names = sorted(names, key=lambda n: order.index(n) if n in order else 999)
    parent = patch_parent(st, names[0])
    topoid = st["patches"][names[-1]]["oid"]
    msg = opts.get("message") or "\n\n".join(get_commit_message(st["patches"][n]["oid"]) for n in names)
    newname = str(opts.get("name") or unique_name(slugify_subject(str(msg).splitlines()[0]), st))
    newoid = commit_tree(tree_of(topoid), [parent], str(msg), opts.get("author_env"))
    # Remove old, insert new where first was.
    for key in ("applied", "unapplied", "hidden"):
        lst = st.get(key, [])
        if any(n in lst for n in names):
            idx = min([lst.index(n) for n in names if n in lst])
            lst = [x for x in lst if x not in names]
            if key == ("applied" if names[0] in st.get("applied", []) else key):
                lst.insert(idx, newname)
            st[key] = lst
    for n in names: st["patches"].pop(n, None)
    st["patches"][newname] = {"oid": newoid}
    if newname in st.get("applied", []): reset_to(newoid, hard=True)
    repo.save(st, "squash")
    println(format_range_line("-", names))
    println(format_range_line("#", names))
    println(f"> {newname}")
    return 0


def cmd_pull(args: List[str]) -> int:
    if help_requested(args, "pull"):
        return 0
    return git_call(["pull"] + args)


def cmd_rebase(args: List[str]) -> int:
    if help_requested(args, "rebase"):
        return 0
    target = next((a for a in args if not a.startswith("-")), None)
    if not target:
        return git_call(["rebase"])
    # Simplified: pop all, reset base, push all.
    repo = Repo(); st = repo.load(create_empty=True)
    old_unapplied = st.get("unapplied", [])[:]
    if st.get("applied"):
        cmd_pop(["--all"])
        st = repo.load(create_empty=True)
    base = git_out(["rev-parse", f"{target}^{{commit}}"])
    st["base"] = base
    reset_to(base, hard=True)
    repo.save(st, "rebase")
    return cmd_push(["--all"]) if st.get("unapplied") and st.get("unapplied") != old_unapplied else 0


def cmd_reset(args: List[str]) -> int:
    if help_requested(args, "reset"):
        return 0
    hard = "--hard" in args
    revs = [a for a in args if not a.startswith("-")]
    target = revs[0] if revs else "HEAD"
    return git_call(["reset", "--hard" if hard else "--mixed", target])


def cmd_spill(args: List[str]) -> int:
    if help_requested(args, "spill"):
        return 0
    # Spill: remove current patch but keep its changes in the worktree.
    repo = Repo(); st = repo.load(create_empty=True)
    if not st.get("applied"): die("no patches applied")
    top = st["applied"][-1]
    parent = patch_parent(st, top)
    diff = git(["diff", parent, st["patches"][top]["oid"]], capture=True).stdout
    cmd_delete([top])
    git(["apply", "-"], input=diff, capture=True)
    return 0


def cmd_fold(args: List[str]) -> int:
    if help_requested(args, "fold"):
        return 0
    files = [a for a in args if not a.startswith("-")]
    data = sys.stdin.read() if not files or files[0] == "-" else Path(files[0]).read_text()
    gp = git(["apply", "--index", "-"], input=data, capture=True)
    if gp.returncode != 0:
        stderr(gp.stderr); return gp.returncode
    return cmd_refresh(["--index"])


def cmd_sync(args: List[str]) -> int:
    if help_requested(args, "sync"):
        return 0
    die("sync is not supported in this repository")
    return 2


def cmd_email(args: List[str]) -> int:
    if help_requested(args, "email"):
        return 0
    # Minimal `format` support: delegate to git format-patch for selected patches.
    return git_call(["format-patch", "HEAD"] if not args else ["format-patch"] + args)


def cmd_patches(args: List[str]) -> int:
    if help_requested(args, "patches"):
        return 0
    paths = [a for a in args if not a.startswith("-")]
    repo = Repo(); st = repo.load(create_empty=True)
    if not paths and git(["diff", "--quiet"], capture=True).returncode == 0:
        die("no local changes and no paths specified")
    for n in all_patch_names(st):
        oid = st["patches"][n]["oid"]
        par = parent_of(oid)
        if not par: continue
        cmd = ["diff", "--name-only", par, oid]
        if paths: cmd += ["--"] + paths
        if git(cmd, capture=True).stdout.strip():
            println(n)
    return 0


def cmd_sink(args: List[str]) -> int:
    if help_requested(args, "sink"):
        return 0
    # Approximate as no-op reorder command.
    repo = Repo(); repo.load(create_empty=True)
    return 0


# ---- Help, completion, aliases, dispatch ------------------------------------


def help_requested(args: List[str], command: str) -> bool:
    if "--help" in args:
        stdout(HELP_TEXTS.get(command, "")); return True
    if "-h" in args:
        stdout(HELP_TEXTS.get(command + "_SHORT", HELP_TEXTS.get(command, ""))); return True
    return False


def cmd_completion(args: List[str]) -> int:
    if help_requested(args, "completion"):
        return 0
    if not args:
        usage_error("error: 'stg completion' requires a subcommand but one was not provided\n  [subcommands: bash, fish, zsh, list, man, help]", usage_for("completion"))
    sub = args[0]
    if sub == "list":
        if len(args) < 2:
            usage_error("error: 'stg completion list' requires a subcommand but one was not provided\n  [subcommands: aliases, commands, commands-and-aliases, help]", "Usage: stg completion list [OPTIONS] <COMMAND>")
        what = args[1]
        if what == "commands":
            stdout("\n".join(COMMANDS) + "\n")
        elif what == "aliases":
            stdout("\n".join(ALIASES) + "\n")
        elif what == "commands-and-aliases":
            stdout("\n".join(COMMANDS + ALIASES) + "\n")
        else:
            usage_error(f"error: unrecognized subcommand '{what}'", "Usage: stg completion list [OPTIONS] <COMMAND>")
        return 0
    if sub == "man":
        return 0
    if sub == "bash":
        stdout("# -*- shell-script -*-\n#\n# SPDX-License-Identifier: GPL-2.0-only\n#\n# bash completion script for StGit (automatically generated)\ncomplete -W \"" + " ".join(COMMANDS + ALIASES) + "\" stg\n")
        return 0
    if sub == "zsh":
        stdout("#compdef stg\n_arguments '1: :(" + " ".join(COMMANDS + ALIASES) + ")'\n")
        return 0
    if sub == "fish":
        stdout("# SPDX-License-Identifier: GPL-2.0-only\n#\n# Fish shell completion for StGit (stg)\ncomplete -c stg -f -a '" + " ".join(COMMANDS + ALIASES) + "'\n")
        return 0
    if sub == "help":
        stdout(HELP_TEXTS.get("completion", "")); return 0
    usage_error(f"error: unrecognized subcommand '{sub}'", usage_for("completion"))
    return 1


def cmd_help(args: List[str]) -> int:
    if not args:
        stdout(HELP_TEXTS.get("TOP_LONG", "")); return 0
    if args[0] == "help":
        stdout(HELP_TEXTS.get("help", "Print this message or the help of the given subcommand(s)\n\nUsage: stg help [COMMAND]...\n")); return 0
    cur = args[0]
    if cur not in ALL_COMMANDS:
        stderr(f"error: unrecognized subcommand '{cur}'\n\nUsage: stg [OPTIONS] <command> [...]\n       stg [OPTIONS] <-h|--help>\n       stg --version\n\nFor more information, try '--help'.\n")
        return 1
    if len(args) > 1:
        extra = args[1]
        stderr(f"error: unrecognized subcommand '{extra}'\n\n{usage_for(cur)}\n\nFor more information, try '--help'.\n")
        return 1
    stdout(HELP_TEXTS.get(cur, ""))
    return 0


def alias_command(cmd: str, args: List[str]) -> int:
    if cmd == "status":
        return git_call(["status", "-s"] + args)
    if cmd in ("add", "resolved"):
        return git_call(["add"] + args)
    if cmd == "rm":
        return git_call(["rm"] + args)
    if cmd == "mv":
        return git_call(["mv"] + args)
    return 1


