}


def parse_global(argv: List[str]) -> Tuple[List[str], Optional[int]]:
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "-C":
            if i + 1 >= len(argv):
                usage_error("error: a value is required for '-C <path>' but none was supplied")
            path = argv[i+1]
            os.chdir(path)
            del argv[i:i+2]
            continue
        if a.startswith("-C") and a != "-C" and len(a) > 2:
            os.chdir(a[2:])
            del argv[i]
            continue
        if a == "--color" or a.startswith("--color="):
            val = None
            if a == "--color":
                if i + 1 >= len(argv):
                    usage_error("error: a value is required for '--color <when>' but none was supplied")
                val = argv[i+1]
                del argv[i:i+2]
            else:
                val = a.split("=", 1)[1]
                del argv[i]
            if val not in COLOR_VALUES:
                stderr(f"error: invalid value '{val}' for '--color <when>'\n  [possible values: auto, always, ansi, never]\n\nFor more information, try '--help'.\n")
                return argv, 1
            continue
        break
    return argv, None


def main(argv: List[str]) -> int:
    argv, early = parse_global(list(argv))
    if early is not None:
        return early
    if not argv:
        stderr(HELP_TEXTS.get("TOP_NOARGS", HELP_TEXTS.get("TOP_SHORT", "")))
        return 1
    if argv[0] == "--version":
        stdout(FULL_VERSION); return 0
    if argv[0] == "version":
        return cmd_version(argv[1:])
    if argv[0] == "--help":
        stdout(HELP_TEXTS.get("TOP_LONG", "")); return 0
    if argv[0] == "-h":
        stdout(HELP_TEXTS.get("TOP_SHORT", HELP_TEXTS.get("TOP_LONG", ""))); return 0
    cmd, args = argv[0], argv[1:]
    if cmd not in ALL_COMMANDS:
        stderr(f"error: unrecognized subcommand '{cmd}'\n\nUsage: stg [OPTIONS] <command> [...]\n       stg [OPTIONS] <-h|--help>\n       stg --version\n\nFor more information, try '--help'.\n")
        return 1
    if cmd in ALIASES:
        return alias_command(cmd, args)
    func = DISPATCH.get(cmd)
    if func is None:
        if help_requested(args, cmd):
            return 0
        die(f"command `{cmd}` is not implemented")
    return func(args)


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except StgError as e:
        # Messages passed through usage_error already include the leading "error:".
        if e.msg.startswith("error:"):
            stderr(e.msg + ("" if e.msg.endswith("\n") else "\n"))
        else:
            stderr(f"error: {e.msg}\n")
        sys.exit(e.code)
    except BrokenPipeError:
        sys.exit(1)
